// Some portions generated by Codex

const EXPLORE_SECTIONS = new Set([
    'outgoing', 'incoming', 'predicate', 'graph', 'types', 'superClasses', 'subClasses',
    'properties', 'superProperties', 'subProperties', 'domain', 'range', 'label', 'comment'
]);
const ABORT_ERRORS = new Set(['net::ERR_ABORTED', 'NS_BINDING_ABORTED', 'cancelled']);

/** Firefox need not emit Chromium's native console message for an expected HTTP error. */
function unexpectedHttpErrorConsoleMessages(messages, status) {
    const expected = new RegExp(`^Failed to load resource: the server responded with a status of ${status}(?:\\s|$)`);
    return messages.length <= 1 && messages.every(message => expected.test(message)) ? [] : messages;
}

/**
 * Mark the controllers a test deliberately leaves, rather than accepting every browser abort. The controller
 * prefix is shared by its queued section requests, so late starts remain attributable to the departed route.
 * A remount receives a new prefix even for the same resource. Compare canonical request resources, not a QName
 * from the page URL. Keep destination assertions after expectNavigation() at each call site.
 */
function createExploreNavigationTracker(page, exploreUrl) {
    const endpoint = new URL(exploreUrl);
    const observed = new Set();
    const departing = new Set();

    function controllerScope(method, address) {
        if (method !== 'GET') return null;
        let url;
        try { url = new URL(address); } catch { return null; }
        if (url.origin !== endpoint.origin || url.pathname !== endpoint.pathname
                || !EXPLORE_SECTIONS.has(url.searchParams.get('section'))
                || !['rows', 'count'].includes(url.searchParams.get('kind'))) return null;
        const resource = url.searchParams.get('resource');
        const id = /^(explore-[a-z0-9]+-[a-z0-9]+-)[1-9][0-9]*$/.exec(url.searchParams.get('query-request-id') || '');
        return resource && id ? JSON.stringify([url.origin, url.pathname, resource, id[1]]) : null;
    }

    page.on('request', request => {
        const scope = controllerScope(request.method(), request.url());
        if (scope) observed.add(scope);
    });

    return {
        expectNavigation() {
            for (const scope of observed) departing.add(scope);
        },
        recordFailure(failure) {
            // Freeze the verdict now: a later navigation must not excuse a failure of the active route.
            return { ...failure, expectedRouteAbort: ABORT_ERRORS.has(failure.error)
                && departing.has(controllerScope(failure.method, failure.url)) };
        }
    };
}

module.exports = { createExploreNavigationTracker, unexpectedHttpErrorConsoleMessages };
